import * as THREE from 'three';
// One geometry + one material; variation lives per instance: size +-20%, offset +-15%, slight rotation, lightness +-8%.
export function makeStoneCourse(count = 60, perRow = 12, rng = Math.random) {
  const geo = new THREE.BoxGeometry(1, 0.5, 0.6);
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92, flatShading: true });
  const mesh = new THREE.InstancedMesh(geo, mat, count); mesh.userData.tag = 'block';
  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3(), c = new THREE.Color();
  const j = () => (rng() - 0.5) * 2;                                   // -1..1
  for (let i = 0; i < count; i++) {
    const row = Math.floor(i / perRow), col = i % perRow;
    s.set(1 + 0.2 * j(), 1 + 0.2 * j(), 1 + 0.2 * j());               // +-20% size
    p.set(col * 1.05 + 0.15 * j() + (row % 2) * 0.5, row * 0.52, 0.09 * j());   // +-15% offset, running bond
    if (col > 0 && col % 4 === 0) p.z += 0.12;                        // interrupt every 4-unit run (buttress step)
    q.setFromEuler(new THREE.Euler(0.03 * j(), 0.04 * j(), 0.02 * j()));
    mesh.setMatrixAt(i, m.compose(p, q, s));
    c.setHSL(0.08 + 0.01 * j(), 0.12, 0.42 + 0.08 * j());             // +-8% lightness, >= 3 value steps across the run
    mesh.setColorAt(i, c);
  }
  mesh.instanceMatrix.needsUpdate = true; mesh.instanceColor.needsUpdate = true;
  return mesh;
}
// Distant massing per building: yaw +-15 deg, >= 2 stacked volumes with different footprints, a roof form; fade with fog.
export function massingYaw(rng = Math.random) { return THREE.MathUtils.degToRad((rng() - 0.5) * 30); }
